// Generated by P00 from contracts/v1 (frozen design v1.0.0).
// P10/P11/P12 consume these types; do NOT hand-edit divergently from the schemas.
// Amounts, sequence numbers and big integers are always strings (design D13).

export type Id = string; // ^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$
export type Seq = string; // ^(0|[1-9][0-9]*)$
export type Digest = string; // ^[a-f0-9]{64}$

export interface ObjectRef {
  project_id: Id;
  object_type: Id;
  object_id: Id;
  revision_id: Id;
}

export interface SharedKnowledgeRef {
  store_id: Id;
  object_id: Id;
  revision_id: Id;
  digest: Digest;
}

export interface Cursor {
  commit_seq: Seq;
  event_index: number;
}

export interface Selector {
  project_id: Id;
  workspace_id?: Id;
  session_id?: Id;
  task_id?: Id;
  attempt_id?: Id;
}

export interface ExpectedHead {
  object_ref: ObjectRef;
  pointer_name: "draft" | "current";
  expected_head_version: Seq;
}

export interface SourceKey {
  host_id: Id;
  origin_session_id: Id;
  log_generation: Id;
  source_seq: Seq;
}

export interface ArtifactRef {
  artifact_id: Id;
  sha256: Digest;
  size_bytes: Seq;
  media_type: string;
  required: boolean;
}

export interface Amount {
  value: string;
  unit: "USD" | "CNY" | "tokens" | "seconds";
}

export interface AcceptanceItem {
  item_id: Id;
  requirement_ref: ObjectRef;
  recipe_ref: ObjectRef;
  required: boolean;
  evidence_type: "automated_test" | "human_review" | "artifact_check";
  criterion: string;
}

export interface Strategy {
  strategy_id: Id;
  title: string;
  hypothesis: string;
  risks: string[];
  acceptance_refs: ObjectRef[];
  environment_requirements: ObjectRef[];
  budget_ref?: ObjectRef;
}

export interface SafeDetail {
  key: Id;
  value: string;
}

export interface BlockError {
  code: Id;
  message: string;
  retryable: boolean;
  category: "input" | "permission" | "conflict" | "business" | "infrastructure" | "unknown";
  safe_details: SafeDetail[];
  recovery_action: string;
  related_refs: ObjectRef[];
}

export type ResultSource =
  | { kind: "session_event"; source_key: SourceKey; payload_digest: Digest }
  | {
      kind: "provider_result";
      provider_id: Id;
      run_id: Id;
      result_id: Id;
      epoch: Seq;
      payload_digest: Digest;
    };

export interface ProviderCapabilities {
  provider_id: Id;
  supported_actions: Id[];
  supported_sandbox_level: "none" | "directory_only" | "partial" | "os_enforced" | "unknown";
  can_cancel: boolean;
  can_query_effect: boolean;
  idempotent_apply: boolean;
  external_fencing: boolean;
  durable_result: boolean;
  model_usage_available: boolean;
}

export type ReceiptStatus = "committed" | "accepted" | "rejected";
export type ReceiptDomain = "identity" | "project";

export interface CommandReceipt {
  command_id: Id;
  idempotency_key: Id;
  command: string;
  status: ReceiptStatus;
  commit_seq: Seq;
  event_cursor: Cursor;
  object_refs: ObjectRef[];
  result_refs: ObjectRef[];
  committed_at: string;
  receipt_domain: ReceiptDomain;
  store_id: Id;
  operation_id?: Id;
  error?: BlockError;
}

export interface DeliverySnapshotBody {
  schema_version: "1.0.0";
  canonicalization: "rfc8785";
  evidence_mode: "production" | "test";
  project_id: Id;
  task_ref: ObjectRef;
  selected_attempt_ref: ObjectRef;
  packet_ref: ObjectRef;
  requirement_refs: ObjectRef[];
  design_refs: ObjectRef[];
  acceptance_refs: ObjectRef[];
  rule_refs: ObjectRef[];
  scope_ref: ObjectRef;
  input_manifest_ref: ObjectRef;
  context_manifest_ref: ObjectRef;
  environment_ref: ObjectRef;
  verification_refs: ObjectRef[];
  candidate_digest: Digest;
  delivery: { method: "bundle"; target_ref: ObjectRef };
  artifacts: ArtifactRef[];
}

export interface CommandEnvelope {
  jsonrpc: "2.0";
  id: Id;
  method: "kernel.command";
  params: {
    protocol_version: "1.0.0";
    invocation_context_id: Id;
    idempotency_key: Id;
    command: string;
    selector: Selector;
    expected_heads: ExpectedHead[];
    payload: Record<string, unknown>;
  };
}

export interface QueryEnvelope {
  jsonrpc: "2.0";
  id: Id;
  method: "kernel.query";
  params: {
    protocol_version: "1.0.0";
    invocation_context_id: Id;
    selector: Selector;
    query: string;
    payload: Record<string, unknown>;
    as_of_seq?: Seq;
    page_token?: string;
  };
}
